def check_solution(p, a, b):
    if p <= 2 or not isinstance(p, int): return False
    if a <= 0 or b <= 0: return False
    if a > b: return False

    val1 = a**(p-1) + b
    val2 = b**(p-1) + a

    def is_power(n, p):
        if n <= 0: return False
        while n > 1 and n % p == 0:
            n //= p
        return n == 1

    return is_power(val1, p) and is_power(val2, p)

